const res = $input.first().json;

// A non-2xx from Firecrawl does not come out of this node's error input —
// n8n hands it down the *success* branch as an ordinary item. Catch it here,
// or it surfaces on the next line as "Cannot read properties of undefined
// (reading 'web')", which points at the parsing rather than at Firecrawl.
if (res.error || res.success === false) {
  const detail =
    res.body?.error ||
    res.details?.description ||
    res.error?.message ||
    JSON.stringify(res.error);
  const code = res.httpCode || res.error?.status || '';
  const wait = res.body?.retry_after_seconds;
  throw new Error(
    `Firecrawl request failed${code ? ` (${code})` : ''}: ${detail}` +
    (wait ? ` Retry in ~${Math.round(wait / 3600)}h.` : '')
  );
}

const results = res.data?.web || [];

const scraped = results.filter(r => r.markdown);

// Every result blocked or unscrapable means the gap analysis has nothing to
// read, and Claude would happily invent an article from an empty brief.
if (!scraped.length) {
  throw new Error(
    `Firecrawl returned ${results.length} result(s) and none had markdown — ` +
    'nothing to analyse for this topic.'
  );
}

const competitor_markdown = scraped
  .map(r => `## ${r.title}\n(${r.url})\n\n${r.markdown.slice(0, 4000)}`)
  .join('\n\n---\n\n');

return [{
  json: {
    topic: $('Google Sheets Trigger').first().json.topic,
    competitor_count: scraped.length,
    competitor_markdown,
  }
}];

