// claude-opus-5 has extended thinking on, so content[0] is a *thinking* block.
// Find the text block by type instead of assuming index 0.
const res = $input.first().json;
const content = res.content || [];
const textBlock = content.find(b => b.type === 'text');
if (!textBlock) {
  throw new Error('No text block in Claude response — got: ' + content.map(b => b.type).join(', '));
}
// A truncated response leaves invalid JSON. Say so plainly: otherwise this
// surfaces three lines down as "Unterminated string in JSON at position N".
if (res.stop_reason === 'max_tokens') {
  throw new Error('Claude hit max_tokens and the JSON is cut off. Raise max_tokens on the previous node. Output so far: ' + textBlock.text.length + ' chars.');
}

// The analysis JSON arrives as a *string* — parse it.
const analysis = JSON.parse(textBlock.text);

return [{
  json: {
    topic: $('Flatten Competitors').first().json.topic,
    competitor_count: $('Flatten Competitors').first().json.competitor_count,
    analysis,
  }
}];

