// claude-opus-5 has extended thinking on, so content[0] is a *thinking* block.
// Find the text block by type instead of assuming index 0.
const res = $input.first().json;
const content = res.content || [];
const textBlock = content.find(b => b.type === 'text');
if (!textBlock) {
  throw new Error('No text block in Claude response — got: ' + content.map(b => b.type).join(', '));
}
// A truncated response leaves invalid JSON. Say so plainly: otherwise this
// surfaces three lines down as "Unterminated string in JSON at position N".
if (res.stop_reason === 'max_tokens') {
  throw new Error('Claude hit max_tokens and the JSON is cut off. Raise max_tokens on the previous node. Output so far: ' + textBlock.text.length + ' chars.');
}

// Parse the article, then convert its markdown into Notion block objects.
const article = JSON.parse(textBlock.text);

const rt = (t) => [{ type: 'text', text: { content: t.slice(0, 2000) } }];

const blocks = article.body_markdown
  .split('\n')
  .map(l => l.trim())
  .filter(Boolean)
  .map(line => {
    if (line.startsWith('### ')) {
      return { object: 'block', type: 'heading_3', heading_3: { rich_text: rt(line.slice(4)) } };
    }
    if (line.startsWith('## ')) {
      return { object: 'block', type: 'heading_2', heading_2: { rich_text: rt(line.slice(3)) } };
    }
    if (line.startsWith('- ')) {
      return { object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: rt(line.slice(2)) } };
    }
    return { object: 'block', type: 'paragraph', paragraph: { rich_text: rt(line) } };
  })
  .slice(0, 100); // Notion rejects more than 100 children per create call

return [{
  json: {
    topic: $('Parse Gap Analysis').first().json.topic,
    title: article.title,
    meta_description: article.meta_description,
    tags: article.tags,
    gaps_addressed: article.gaps_addressed,
    blocks,
  }
}];

